    /// <summary>引导编辑器的类型映射、步骤操作和只读配置检查。</summary>
    internal static class GuideEditorModel
    {
        #region 内部参数

        internal static readonly string[] EventNames =
            { "无事件", "页面打开", "页面关闭", "UI 按钮点击", "延时结束", "引导遮罩点击", "自定义事件" };
        internal static readonly string[] ExecutorNames =
            { "打开遮罩", "关闭遮罩", "显示小手", "关闭小手", "打开页面", "关闭页面", "延时", "显示提示", "输出日志" };
        internal static readonly string[] ConditionNames =
            { "未设置", "恒真", "恒假", "由指定事件触发", "页面显示状态", "引导已完成", "整数比较", "全部满足（AND）", "任一满足（OR）" };

