        #region 内部方法

        private static void CheckCondition(GuideConditionBase condition, string path, List<string> issues,
            HashSet<GuideConditionBase> visiting)
        {
            if (condition == null) return;
            if (!visiting.Add(condition)) { issues.Add(path + "存在循环条件引用。"); return; }
            if (condition is GuideConditionGroup group)
            {
                if (group.conditions == null || group.conditions.Count == 0)
                    issues.Add(path + "是空条件组：AND 恒真，OR 恒假。");
                if (group.conditions != null)
                    foreach (var child in group.conditions) CheckCondition(child, path + " / 子条件", issues, visiting);
            }
            else if (condition is GuideCondition single)
            {
                if (!Enum.IsDefined(typeof(GuideConditionType), single.conditionType)) issues.Add(path + "的条件类型无效。");
                CheckParameter(single, single.conditionParams, path, issues);
            }
            visiting.Remove(condition);
        }

        private static void CheckItems<T>(List<T> items, string path, List<string> issues)
        {
            if (items == null) return;
            for (var i = 0; i < items.Count; i++)
            {
                var itemPath = path + $" #{i + 1}";
                if (items[i] is GuideEvent e)
                {
                    if (e.eventType == GuideEventType.None || !Enum.IsDefined(typeof(GuideEventType), e.eventType))
                        issues.Add(itemPath + "未选择有效事件。");
                    CheckParameter(e, e.eventParam, itemPath, issues);
                }
                else if (items[i] is GuideExecutor executor)
                {
                    if (!Enum.IsDefined(typeof(GuideExecuteType), executor.executeType)) issues.Add(itemPath + "的执行类型无效。");
                    CheckParameter(executor, executor.executeParam, itemPath, issues);
                }
                else issues.Add(itemPath + "为空。");
            }
        }

        private static void CheckParameter(object owner, object parameter, string path, List<string> issues)
        {
            var type = ParameterType(owner);
            if (type != null && (parameter == null || parameter.GetType() != type))
                issues.Add(path + "缺少参数或参数类型不匹配，请使用“创建/重建参数”。");
            if (parameter is GuideExeParamDelay delay && delay.seconds < 0) issues.Add(path + "的延时不能小于 0。");
            if (parameter is GuideExeParamOpenUI open && string.IsNullOrWhiteSpace(open.prefabPath)) issues.Add(path + "没有设置页面路径。");
            if (parameter is GuideExeParamOpenUI page && page.pageType != Ember.UI.PageType.MainPage
                && page.pageType != Ember.UI.PageType.Popup && page.pageType != Ember.UI.PageType.FullScreenPopup
                && page.pageType != Ember.UI.PageType.TopMost)
                issues.Add(path + "的页面类型未被当前打开页面执行器支持，请使用业务执行器处理。");
            if (parameter is GuideExeParamCloseUI close && string.IsNullOrWhiteSpace(close.prefabPath)) issues.Add(path + "没有设置页面路径。");
            if (parameter is GuideExeParamOpenHand hand && string.IsNullOrWhiteSpace(hand.pagePath)) issues.Add(path + "没有设置小手目标页面，运行时无法定位。");
        }

        #endregion

