        #region 外部方法

        internal static Type ParameterType(object value)
        {
            if (value is GuideEvent e)
                return e.eventType switch
                {
                    GuideEventType.OnPageShown or GuideEventType.OnPageHidden => typeof(GuideEventParamPage),
                    GuideEventType.OnClickUIButton => typeof(GuideEventParamClickUI),
                    GuideEventType.OnCustom => typeof(GuideEventParamCustom),
                    _ => null
                };
            if (value is GuideExecutor executor)
                return executor.executeType switch
                {
                    GuideExecuteType.OpenMask => typeof(GuideExeParamMask),
                    GuideExecuteType.OpenHand => typeof(GuideExeParamOpenHand),
                    GuideExecuteType.OpenUI => typeof(GuideExeParamOpenUI),
                    GuideExecuteType.CloseUI => typeof(GuideExeParamCloseUI),
                    GuideExecuteType.Delay => typeof(GuideExeParamDelay),
                    GuideExecuteType.ShowTips => typeof(GuideExeParamShowTips),
                    GuideExecuteType.Log => typeof(GuideExeParamLog),
                    _ => null
                };
            if (value is GuideCondition condition)
                return condition.conditionType switch
                {
                    GuideConditionType.IsTriggerByEvent => typeof(GuideCondParamIsTriggerByEvent),
                    GuideConditionType.IsUIShowing => typeof(GuideCondParamIsUIShowing),
                    GuideConditionType.IsGuideFinished => typeof(GuideCondParamGuideFinished),
                    GuideConditionType.CompareInt => typeof(GuideCondParamCompareInt),
                    _ => null
                };
            return null;
        }

        internal static GuideConditionBase CreateCondition(int selection)
        {
            if (selection == 0) return null;
            if (selection >= 7)
                return new GuideConditionGroup { logicOperator = selection == 7 ? LogicOperator.And : LogicOperator.Or };
            var condition = new GuideCondition { conditionType = (GuideConditionType)selection };
            var type = ParameterType(condition);
            condition.conditionParams = type == null ? null : Activator.CreateInstance(type);
            return condition;
        }

        internal static bool CanEdit(GuideDefine define)
        {
            if (!define || EditorApplication.isPlayingOrWillChangePlaymode) return false;
            var path = AssetDatabase.GetAssetPath(define);
            return path.StartsWith("Assets/", StringComparison.Ordinal)
                && AssetDatabase.IsOpenForEdit(define);
        }

        internal static void AddStep(GuideDefine define, int copyIndex = -1)
        {
            if (!CanEdit(define)) return;
            GuideDefine clone = null;
            try
            {
                var step = new GuideStepDefine { name = "新步骤" };
                if (copyIndex >= 0)
                {
                    // 克隆整个 SO，让嵌套 SerializeReference 由 Unity 深拷贝，避免副本修改原步骤。
                    clone = UnityEngine.Object.Instantiate(define);
                    step = clone.guideSteps[copyIndex];
                    step.name = (step.name ?? "步骤") + "（副本）";
                }
                Undo.RecordObject(define, copyIndex < 0 ? "添加引导步骤" : "复制引导步骤");
                define.guideSteps ??= new List<GuideStepDefine>();
                define.guideSteps.Insert(copyIndex < 0 ? define.guideSteps.Count : copyIndex + 1, step);
                EditorUtility.SetDirty(define);
            }
            finally
            {
                if (clone) UnityEngine.Object.DestroyImmediate(clone);
            }
        }

        internal static List<string> Validate(GuideDefine define)
        {
            var issues = new List<string>();
            if (!define) return issues;
            var visited = new HashSet<GuideConditionBase>();
            CheckCondition(define.baseSkipAll, "全局跳过", issues, visited);
            if (define.guideSteps == null || define.guideSteps.Count == 0)
                issues.Add("尚未添加步骤。");
            if (define.guideSteps == null) return issues;
            for (var i = 0; i < define.guideSteps.Count; i++)
            {
                var s = define.guideSteps[i];
                var prefix = $"步骤 {i + 1}";
                if (s == null) { issues.Add(prefix + "为空。"); continue; }
                if (string.IsNullOrWhiteSpace(s.name)) issues.Add(prefix + "没有填写用途名称。");
                CheckCondition(s.startConditionsToSkipAll, prefix + " / 跳过引导", issues, visited);
                CheckCondition(s.startConditionsToSkip, prefix + " / 跳过步骤", issues, visited);
                CheckCondition(s.startConditionsToSuccess, prefix + " / 开始条件", issues, visited);
                CheckCondition(s.endConditionsToFinishAll, prefix + " / 完成引导", issues, visited);
                CheckCondition(s.endConditionsToCancelAll, prefix + " / 取消引导", issues, visited);
                CheckCondition(s.endConditionsToCancel, prefix + " / 取消步骤", issues, visited);
                CheckCondition(s.endConditionsToSuccess, prefix + " / 完成条件", issues, visited);
                CheckItems(s.startEvents, prefix + " / 开始事件", issues);
                CheckItems(s.endEvents, prefix + " / 结束事件", issues);
                CheckItems(s.startExecutors, prefix + " / 开始执行器", issues);
                CheckItems(s.endExecutors, prefix + " / 结束执行器", issues);
                if (s.endConditionsToSuccess == null)
                    issues.Add(prefix + "未设置完成条件：进入后会立即完成；需要等待点击或延时时，请配置结束事件和完成条件。");
                if (!s.needUpdate && s.endConditionsToSuccess != null && (s.endEvents == null || s.endEvents.Count == 0))
                    issues.Add(prefix + "设置了完成条件，但没有结束事件且未启用每帧检查，条件变化可能无法推进。");
            }
            return issues;
        }

        #endregion
